esbmc_test_source:
contract InvMutTest {
    C c;
    address creator;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function with inputs: target address for migrateTo
    function run(address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Observe contract balance before
        uint256 beforeBal = address(c).balance;

        // Try calling migrateTo and record whether it reverted
        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After call: if it did not revert, contract balance must be zero and the recipient's balance must have increased by beforeBal.
        // We can observe address(c).balance and address(this).balance; but we cannot observe arbitrary `to` balance if it's not this contract.
        // Therefore, when the call does not revert, require that contract balance is zero. Also require that, if `to` equals address(this), our balance increased by beforeBal.
        // Formulate a single general assert capturing both cases:
        // - If reverted == false then address(c).balance == 0
        // - And additionally: if reverted == false and to == address(this) then address(this).balance >= beforeBal

        assert(
            (reverted == true) ||
            (address(c).balance == 0 && (to != address(this) || address(this).balance >= beforeBal))
        );
    }

    // accept Ether so migrateTo can send to this contract
    receive() external payable {}
}

